//go:build integration

package integration

import (
	"bytes"
	"encoding/json"
	"os"
	"os/exec"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// TestShadow_CommitBeforeStop tests the "commit while agent is still working" flow.
//
// When the user commits while the agent is in the ACTIVE phase (between
// SimulateUserPromptSubmit and SimulateStop), the session should transition to
// ACTIVE_COMMITTED. This defers condensation because the agent is still working.
// When the agent finishes its turn (SimulateStop), the deferred condensation fires
// and the session transitions to IDLE with metadata persisted to entire/checkpoints/v1.
//
// State machine transitions tested:
//   - ACTIVE + GitCommit -> ACTIVE_COMMITTED (defer condensation, migrate shadow branch)
//   - ACTIVE_COMMITTED + TurnEnd -> IDLE + ActionCondense (deferred condensation fires)
func TestShadow_CommitBeforeStop(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t, strategy.StrategyNameManualCommit)

	// ========================================
	// Phase 1: Start session and create initial checkpoint
	// ========================================
	t.Log("Phase 1: Start session and create initial work")

	sess := env.NewSession()

	// Pass transcript path in the hook input so it's stored in session state
	// (needed for mid-session commit detection via live transcript)
	submitWithTranscriptPath := func(sessionID, transcriptPath string) {
		t.Helper()
		input := map[string]string{
			"session_id":      sessionID,
			"transcript_path": transcriptPath,
		}
		inputJSON, _ := json.Marshal(input)
		cmd := exec.Command(getTestBinary(), "hooks", "claude-code", "user-prompt-submit")
		cmd.Dir = env.RepoDir
		cmd.Stdin = bytes.NewReader(inputJSON)
		cmd.Env = append(os.Environ(),
			"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
		)
		if output, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("user-prompt-submit failed: %v\nOutput: %s", err, output)
		}
	}

	submitWithTranscriptPath(sess.ID, sess.TranscriptPath)

	// Verify session is ACTIVE
	state, err := env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state == nil {
		t.Fatal("Session state should exist")
	}
	if state.Phase != session.PhaseActive {
		t.Errorf("Phase after first prompt should be %q, got %q", session.PhaseActive, state.Phase)
	}

	// Create a file and transcript, then stop (first checkpoint)
	env.WriteFile("feature.go", "package main\n\nfunc Feature() {}\n")
	sess.CreateTranscript("Create feature function", []FileChange{
		{Path: "feature.go", Content: "package main\n\nfunc Feature() {}\n"},
	})
	if err := env.SimulateStop(sess.ID, sess.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (checkpoint 1) failed: %v", err)
	}

	// Verify session is IDLE after stop
	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state == nil {
		t.Fatal("Session state should exist")
	}
	if state.Phase != session.PhaseIdle {
		t.Errorf("Phase after first stop should be %q, got %q", session.PhaseIdle, state.Phase)
	}
	if state.StepCount != 1 {
		t.Errorf("StepCount after first checkpoint should be 1, got %d", state.StepCount)
	}

	// Verify shadow branch was created
	initialHead := state.BaseCommit
	shadowBranch := env.GetShadowBranchNameForCommit(initialHead)
	if !env.BranchExists(shadowBranch) {
		t.Fatalf("Shadow branch %s should exist after first checkpoint", shadowBranch)
	}

	// ========================================
	// Phase 2: Start new turn and create more work
	// ========================================
	t.Log("Phase 2: Start new turn, create more work")

	submitWithTranscriptPath(sess.ID, sess.TranscriptPath)

	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state.Phase != session.PhaseActive {
		t.Errorf("Phase after second prompt should be %q, got %q", session.PhaseActive, state.Phase)
	}

	// Create another file and write updated transcript
	env.WriteFile("utils.go", "package main\n\nfunc Util() {}\n")
	sess.TranscriptBuilder = NewTranscriptBuilder()
	sess.CreateTranscript("Create utils", []FileChange{
		{Path: "utils.go", Content: "package main\n\nfunc Util() {}\n"},
	})

	// Do NOT stop yet -- the agent is still ACTIVE

	// ========================================
	// Phase 3: User commits while agent is ACTIVE
	// ========================================
	t.Log("Phase 3: User commits while agent is ACTIVE")

	headBefore := env.GetHeadHash()
	env.GitCommitWithShadowHooks("Add feature and utils", "feature.go", "utils.go")
	commitHash := env.GetHeadHash()

	if commitHash == headBefore {
		t.Fatal("Commit was not created")
	}

	// Verify checkpoint trailer was added
	checkpointID := env.GetCheckpointIDFromCommitMessage(commitHash)
	if checkpointID == "" {
		t.Log("Note: checkpoint trailer may not be present if no shadow branch content was detected (mid-session commit scenario)")
	} else {
		t.Logf("Commit has checkpoint trailer: %s", checkpointID)
	}

	// CRITICAL: Verify session phase is ACTIVE_COMMITTED
	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state == nil {
		t.Fatal("Session state should exist after commit")
	}
	if state.Phase != session.PhaseActiveCommitted {
		t.Errorf("Phase after commit-while-active should be %q, got %q",
			session.PhaseActiveCommitted, state.Phase)
	}
	t.Logf("Session phase after mid-turn commit: %s", state.Phase)

	// Verify shadow branch was migrated to the new HEAD
	// The old shadow branch (based on initialHead) may still exist or be cleaned up.
	// The important thing is that the session's BaseCommit was updated.
	if state.BaseCommit == initialHead {
		t.Logf("Note: BaseCommit not yet updated (may happen during migration)")
	}

	// ========================================
	// Phase 4: Agent finishes turn (SimulateStop)
	// ========================================
	t.Log("Phase 4: Agent finishes turn (SimulateStop)")

	if err := env.SimulateStop(sess.ID, sess.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (after commit) failed: %v", err)
	}

	// Verify session transitions to IDLE
	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state == nil {
		t.Fatal("Session state should exist after stop")
	}
	if state.Phase != session.PhaseIdle {
		t.Errorf("Phase after stop from ACTIVE_COMMITTED should be %q, got %q",
			session.PhaseIdle, state.Phase)
	}
	t.Logf("Session phase after stop: %s (StepCount: %d)", state.Phase, state.StepCount)

	// Deferred condensation should have fired during TurnEnd (ACTIVE_COMMITTED → IDLE).
	// Verify StepCount was reset and metadata was persisted to entire/checkpoints/v1.
	if state.StepCount != 0 {
		t.Errorf("StepCount should be 0 after TurnEnd condensation, got %d", state.StepCount)
	}

	if !env.BranchExists(paths.MetadataBranchName) {
		t.Fatal("entire/checkpoints/v1 branch should exist after TurnEnd condensation")
	}
	latestCheckpointID := env.TryGetLatestCheckpointID()
	if latestCheckpointID != "" {
		summaryPath := CheckpointSummaryPath(latestCheckpointID)
		if !env.FileExistsInBranch(paths.MetadataBranchName, summaryPath) {
			t.Errorf("Checkpoint metadata should exist at %s", summaryPath)
		} else {
			t.Logf("Condensed data exists at checkpoint %s", latestCheckpointID)
		}
	}

	t.Log("CommitBeforeStop test completed successfully")
}

// TestShadow_AmendPreservesTrailer tests that `git commit --amend` preserves
// the checkpoint trailer from the original commit.
//
// When a user amends a commit that has an Entire-Checkpoint trailer, the
// prepare-commit-msg hook (called with source="commit") should preserve the
// existing trailer. No duplicate condensation should occur.
//
// Hook behavior tested:
//   - prepare-commit-msg with source="commit": preserves existing trailer
//   - post-commit after amend: no duplicate condensation
func TestShadow_AmendPreservesTrailer(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t, strategy.StrategyNameManualCommit)

	// ========================================
	// Phase 1: Full workflow - create checkpoint and commit
	// ========================================
	t.Log("Phase 1: Create session, checkpoint, and commit")

	sess := env.NewSession()
	if err := env.SimulateUserPromptSubmit(sess.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	// Create a file and checkpoint
	env.WriteFile("main.go", "package main\n\nfunc main() {}\n")
	sess.CreateTranscript("Create main.go", []FileChange{
		{Path: "main.go", Content: "package main\n\nfunc main() {}\n"},
	})
	if err := env.SimulateStop(sess.ID, sess.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Commit with hooks (triggers condensation)
	env.GitCommitWithShadowHooks("Initial implementation", "main.go")

	originalCommitHash := env.GetHeadHash()
	originalCheckpointID := env.GetCheckpointIDFromCommitMessage(originalCommitHash)
	if originalCheckpointID == "" {
		t.Fatal("Original commit should have a checkpoint trailer")
	}
	t.Logf("Original commit %s has checkpoint ID: %s", originalCommitHash[:7], originalCheckpointID)

	// Verify condensation happened
	if !env.BranchExists(paths.MetadataBranchName) {
		t.Fatal("entire/checkpoints/v1 branch should exist after condensation")
	}

	// Record the sessions branch state for later comparison
	sessionsCommitBefore := env.GetLatestCommitMessageOnBranch(paths.MetadataBranchName)
	t.Logf("Sessions branch commit before amend:\n%s", sessionsCommitBefore)

	// ========================================
	// Phase 2: Amend the commit
	// ========================================
	t.Log("Phase 2: Amend the commit")

	// Amend with the same message (simulating a minor message edit or staging additional files)
	env.GitCommitAmendWithShadowHooks("Initial implementation (amended)")

	amendedCommitHash := env.GetHeadHash()
	t.Logf("Amended commit: %s", amendedCommitHash[:7])

	// The amended commit hash should be different from the original
	if amendedCommitHash == originalCommitHash {
		t.Error("Amended commit should have a different hash")
	}

	// ========================================
	// Phase 3: Verify trailer is preserved
	// ========================================
	t.Log("Phase 3: Verify checkpoint trailer is preserved")

	amendedCheckpointID := env.GetCheckpointIDFromCommitMessage(amendedCommitHash)
	if amendedCheckpointID == "" {
		t.Fatal("Amended commit should still have a checkpoint trailer")
	}
	t.Logf("Amended commit has checkpoint ID: %s", amendedCheckpointID)

	// The checkpoint ID should be the SAME as the original
	if amendedCheckpointID != originalCheckpointID {
		t.Errorf("Amended commit should preserve original checkpoint ID.\nOriginal: %s\nAmended:  %s",
			originalCheckpointID, amendedCheckpointID)
	}

	// ========================================
	// Phase 4: Verify no duplicate condensation
	// ========================================
	t.Log("Phase 4: Verify no duplicate condensation")

	// The sessions branch commit should not have changed (no new condensation)
	sessionsCommitAfter := env.GetLatestCommitMessageOnBranch(paths.MetadataBranchName)
	if sessionsCommitBefore != sessionsCommitAfter {
		t.Logf("Sessions branch commit changed after amend:\nBefore:\n%s\nAfter:\n%s",
			sessionsCommitBefore, sessionsCommitAfter)
		// This is not necessarily an error -- post-commit might trigger condensation
		// if there's new content. But with no new session activity, it should be the same.
		t.Log("Note: sessions branch was updated (may indicate duplicate condensation)")
	} else {
		t.Log("Sessions branch unchanged after amend (no duplicate condensation)")
	}

	// Verify the checkpoint data still exists and is accessible
	summaryPath := CheckpointSummaryPath(originalCheckpointID)
	if !env.FileExistsInBranch(paths.MetadataBranchName, summaryPath) {
		t.Errorf("Checkpoint metadata should still exist at %s after amend", summaryPath)
	}

	transcriptPath := SessionFilePath(originalCheckpointID, paths.TranscriptFileName)
	if !env.FileExistsInBranch(paths.MetadataBranchName, transcriptPath) {
		t.Errorf("Transcript should still exist at %s after amend", transcriptPath)
	}

	t.Log("AmendPreservesTrailer test completed successfully")
}

package strategy

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestPrepareCommitMsg_AmendPreservesExistingTrailer verifies that when amending
// a commit that already has an Entire-Checkpoint trailer, the trailer is preserved
// unchanged. source="commit" indicates an amend operation.
func TestPrepareCommitMsg_AmendPreservesExistingTrailer(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	s := &ManualCommitStrategy{}

	sessionID := "test-session-amend-preserve"
	err := s.InitializeSession(sessionID, agent.AgentTypeClaudeCode, "", "")
	require.NoError(t, err)

	// Write a commit message file that already has the trailer
	commitMsgFile := filepath.Join(t.TempDir(), "COMMIT_EDITMSG")
	existingMsg := "Original commit message\n\nEntire-Checkpoint: abc123def456\n"
	require.NoError(t, os.WriteFile(commitMsgFile, []byte(existingMsg), 0o644))

	// Call PrepareCommitMsg with source="commit" (amend)
	err = s.PrepareCommitMsg(commitMsgFile, "commit")
	require.NoError(t, err)

	// Read the file back and verify the trailer is still present
	content, err := os.ReadFile(commitMsgFile)
	require.NoError(t, err)

	cpID, found := trailers.ParseCheckpoint(string(content))
	assert.True(t, found, "trailer should still be present after amend")
	assert.Equal(t, "abc123def456", cpID.String(),
		"trailer should preserve the original checkpoint ID")
}

// TestPrepareCommitMsg_AmendRestoresTrailerFromLastCheckpointID verifies the amend
// bug fix: when a user does `git commit --amend -m "new message"`, the Entire-Checkpoint
// trailer is lost because the new message replaces the old one. PrepareCommitMsg restores
// the trailer from LastCheckpointID in session state.
func TestPrepareCommitMsg_AmendRestoresTrailerFromLastCheckpointID(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	s := &ManualCommitStrategy{}

	sessionID := "test-session-amend-restore"
	err := s.InitializeSession(sessionID, agent.AgentTypeClaudeCode, "", "")
	require.NoError(t, err)

	// Simulate state after condensation: LastCheckpointID is set
	state, err := s.loadSessionState(sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	state.LastCheckpointID = "abc123def456"
	err = s.saveSessionState(state)
	require.NoError(t, err)

	// Write a commit message file with NO trailer (user did --amend -m "new message")
	commitMsgFile := filepath.Join(t.TempDir(), "COMMIT_EDITMSG")
	newMsg := "New amended message\n"
	require.NoError(t, os.WriteFile(commitMsgFile, []byte(newMsg), 0o644))

	// Call PrepareCommitMsg with source="commit" (amend)
	err = s.PrepareCommitMsg(commitMsgFile, "commit")
	require.NoError(t, err)

	// Read the file back - trailer should be restored from LastCheckpointID
	content, err := os.ReadFile(commitMsgFile)
	require.NoError(t, err)

	cpID, found := trailers.ParseCheckpoint(string(content))
	assert.True(t, found,
		"trailer should be restored from LastCheckpointID on amend")
	assert.Equal(t, "abc123def456", cpID.String(),
		"restored trailer should use LastCheckpointID value")
}

// TestPrepareCommitMsg_AmendNoTrailerNoLastCheckpointID verifies that when amending with
// no existing trailer and no LastCheckpointID in session state, no trailer is added.
// This is the case where the session has never been condensed yet.
func TestPrepareCommitMsg_AmendNoTrailerNoLastCheckpointID(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	s := &ManualCommitStrategy{}

	sessionID := "test-session-amend-no-id"
	err := s.InitializeSession(sessionID, agent.AgentTypeClaudeCode, "", "")
	require.NoError(t, err)

	// Verify LastCheckpointID is empty (default)
	state, err := s.loadSessionState(sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	assert.True(t, state.LastCheckpointID.IsEmpty(), "LastCheckpointID should be empty by default")

	// Write a commit message file with NO trailer
	commitMsgFile := filepath.Join(t.TempDir(), "COMMIT_EDITMSG")
	newMsg := "Amended without any session context\n"
	require.NoError(t, os.WriteFile(commitMsgFile, []byte(newMsg), 0o644))

	// Call PrepareCommitMsg with source="commit" (amend)
	err = s.PrepareCommitMsg(commitMsgFile, "commit")
	require.NoError(t, err)

	// Read the file back - no trailer should be added
	content, err := os.ReadFile(commitMsgFile)
	require.NoError(t, err)

	_, found := trailers.ParseCheckpoint(string(content))
	assert.False(t, found,
		"no trailer should be added when PendingCheckpointID is empty")

	// Message should be unchanged
	assert.Equal(t, newMsg, string(content),
		"commit message should be unchanged when no trailer to restore")
}

// TestPrepareCommitMsg_NormalCommitGeneratesFreshID verifies that during
// a normal commit (source=""), if the session has new content on the shadow
// branch, a fresh checkpoint ID is generated.
func TestPrepareCommitMsg_NormalCommitGeneratesFreshID(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	s := &ManualCommitStrategy{}

	sessionID := "test-session-normal-fresh-id"
	err := s.InitializeSession(sessionID, agent.AgentTypeClaudeCode, "", "")
	require.NoError(t, err)

	// Create content on the shadow branch so filterSessionsWithNewContent finds it
	createShadowBranchWithTranscript(t, dir, sessionID)

	// Set the session to ACTIVE with a checkpoint on the shadow branch
	state, err := s.loadSessionState(sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	state.Phase = session.PhaseActive
	// Ensure StepCount reflects that a checkpoint exists on the shadow branch
	state.StepCount = 1
	err = s.saveSessionState(state)
	require.NoError(t, err)

	// Write a commit message file with no trailer (normal editor flow)
	commitMsgFile := filepath.Join(t.TempDir(), "COMMIT_EDITMSG")
	normalMsg := "Feature: add new functionality\n"
	require.NoError(t, os.WriteFile(commitMsgFile, []byte(normalMsg), 0o644))

	// Call PrepareCommitMsg with source="" (normal commit, editor flow)
	err = s.PrepareCommitMsg(commitMsgFile, "")
	require.NoError(t, err)

	// Read the file back - trailer should be present with a fresh ID
	content, err := os.ReadFile(commitMsgFile)
	require.NoError(t, err)

	cpID, found := trailers.ParseCheckpoint(string(content))
	assert.True(t, found,
		"trailer should be present for normal commit with active session content")
	assert.NotEmpty(t, cpID.String(),
		"normal commit should generate a fresh checkpoint ID")
}

// createShadowBranchWithTranscript creates a shadow branch commit with a minimal
// transcript file so that filterSessionsWithNewContent detects new content.
// This uses low-level go-git plumbing to create the branch directly.
func createShadowBranchWithTranscript(t *testing.T, repoDir string, sessionID string) {
	t.Helper()

	repo, err := git.PlainOpen(repoDir)
	require.NoError(t, err)

	head, err := repo.Head()
	require.NoError(t, err)
	baseCommit := head.Hash().String()

	// Build the tree with a transcript file at the expected path
	metadataDir := paths.EntireMetadataDir + "/" + sessionID
	transcriptPath := metadataDir + "/" + paths.TranscriptFileName
	transcriptContent := `{"type":"message","role":"assistant","content":"hello"}` + "\n"

	// Create blob for transcript
	blobObj := &plumbing.MemoryObject{}
	blobObj.SetType(plumbing.BlobObject)
	blobObj.SetSize(int64(len(transcriptContent)))
	writer, err := blobObj.Writer()
	require.NoError(t, err)
	_, err = writer.Write([]byte(transcriptContent))
	require.NoError(t, err)
	require.NoError(t, writer.Close())

	blobHash, err := repo.Storer.SetEncodedObject(blobObj)
	require.NoError(t, err)

	// Build nested tree structure: .entire/metadata/<sessionID>/full.jsonl
	// We need to build trees bottom-up
	innerTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: paths.TranscriptFileName, Mode: 0o100644, Hash: blobHash},
		},
	}
	innerTreeObj := repo.Storer.NewEncodedObject()
	innerTreeObj.SetType(plumbing.TreeObject)
	require.NoError(t, innerTree.Encode(innerTreeObj))
	innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
	require.NoError(t, err)

	// Build .entire/metadata/<sessionID> level
	sessionTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: sessionID, Mode: 0o040000, Hash: innerTreeHash},
		},
	}
	sessionTreeObj := repo.Storer.NewEncodedObject()
	sessionTreeObj.SetType(plumbing.TreeObject)
	require.NoError(t, sessionTree.Encode(sessionTreeObj))
	sessionTreeHash, err := repo.Storer.SetEncodedObject(sessionTreeObj)
	require.NoError(t, err)

	// Build .entire/metadata level
	metadataTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: "metadata", Mode: 0o040000, Hash: sessionTreeHash},
		},
	}
	metadataTreeObj := repo.Storer.NewEncodedObject()
	metadataTreeObj.SetType(plumbing.TreeObject)
	require.NoError(t, metadataTree.Encode(metadataTreeObj))
	metadataTreeHash, err := repo.Storer.SetEncodedObject(metadataTreeObj)
	require.NoError(t, err)

	// Build .entire level
	entireTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: ".entire", Mode: 0o040000, Hash: metadataTreeHash},
		},
	}
	entireTreeObj := repo.Storer.NewEncodedObject()
	entireTreeObj.SetType(plumbing.TreeObject)
	require.NoError(t, entireTree.Encode(entireTreeObj))
	entireTreeHash, err := repo.Storer.SetEncodedObject(entireTreeObj)
	require.NoError(t, err)

	// Create commit on shadow branch
	now := time.Now()
	commitObj := &object.Commit{
		Author: object.Signature{
			Name:  "Test",
			Email: "test@test.com",
			When:  now,
		},
		Committer: object.Signature{
			Name:  "Test",
			Email: "test@test.com",
			When:  now,
		},
		Message:  "checkpoint\n\nEntire-Metadata: " + metadataDir + "\nEntire-Session: " + sessionID + "\nEntire-Strategy: manual-commit\n",
		TreeHash: entireTreeHash,
	}
	commitEnc := repo.Storer.NewEncodedObject()
	require.NoError(t, commitObj.Encode(commitEnc))
	commitHash, err := repo.Storer.SetEncodedObject(commitEnc)
	require.NoError(t, err)

	// Create the shadow branch reference
	// WorktreeID is empty for main worktree, which matches what setupGitRepo creates
	shadowBranchName := checkpoint.ShadowBranchNameForCommit(baseCommit, "")
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref := plumbing.NewHashReference(refName, commitHash)
	require.NoError(t, repo.Storer.SetReference(ref))

	// Verify the transcript is readable
	verifyCommit, err := repo.CommitObject(commitHash)
	require.NoError(t, err)
	verifyTree, err := verifyCommit.Tree()
	require.NoError(t, err)
	file, err := verifyTree.File(transcriptPath)
	require.NoError(t, err, "transcript file should exist at %s", transcriptPath)
	content, err := file.Contents()
	require.NoError(t, err)
	require.NotEmpty(t, content, "transcript should have content")
}

